import{_ as e,o as a,c as o,S as t}from"./chunks/framework.f15d8f8c.js";const g=JSON.parse('{"title":"Telegram Addon","description":"","frontmatter":{},"headers":[],"relativePath":"addons/telegram.md","filePath":"addons/telegram.md"}'),l={name:"addons/telegram.md"},s=t(`<h1 id="telegram-addon" tabindex="-1">Telegram Addon <a class="header-anchor" href="#telegram-addon" aria-label="Permalink to &quot;Telegram Addon&quot;">​</a></h1><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><ul><li>The telegram addon support normal account registration, service purchase and reseller panel services, the reseller option can only be accessible if the site have a reseller addon authorization.</li></ul><p>Bind telegram webhook to the website in order to get telegram callback updates. Bot ID and Token required to set webhook.</p><blockquote><p><code>Telegram Bot ID</code>: Your bot id from telegram bot father.</p></blockquote><blockquote><p><code>Telegram Token</code>: Token from telegram bot father.</p></blockquote><blockquote><p><code>Telegram Webhook URL</code>: your website address with tls/ ssl enabled.</p></blockquote><p>Run below command in server terminal (ssh):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">cd</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/home/user/web/tld.com/public_html</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">php</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">console</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">telegram</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">set</span></span></code></pre></div><p>On successfull results, go to your bot and send command /id to get Chat ID. To get group chat id, add the bot to the group with administrator previllages and send /id to get Group Chat ID</p><blockquote><p>Telegram Admin IDs: multiple telegram IDs to send website admin notices or status to. For example if website is manage by more than one person. each id is seperated with a comma. 123456789, 65489731898</p></blockquote><blockquote><p>Telegram Group Group Ban Time: The number of days a user will be ban from the group chat.</p></blockquote><blockquote><p>Telegram Group Activation Timeout: To join a group, activation is required by accepting group rules within a specific time else user will be bannned from joining group.</p></blockquote><h2 id="telegram-support" tabindex="-1">Telegram support <a class="header-anchor" href="#telegram-support" aria-label="Permalink to &quot;Telegram support&quot;">​</a></h2><ul><li><p>User account registration</p></li><li><p>Login notification</p></li><li><p>Service expire notification</p></li><li><p>Service reset notification.</p></li><li><p>Service created notification</p></li><li><p>Website notices to users and group chat</p></li><li><p>Tickets replying (Admin only)</p></li><li><p>Server status notification (Admin only)</p></li><li><p>Website database backup</p></li></ul>`,15),r=[s];function n(i,p,c,d,m,u){return a(),o("div",null,r)}const b=e(l,[["render",n]]);export{g as __pageData,b as default};
